import math

def newman_prime(n):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(math.sqrt(num)) + 1):
            if num % i == 0:
                return False
        return True

    def nsw_sequence():
        a, b = 1, 1
        yield a
        while True:
            yield b
            a, b = b, a + b * b

    count = 0
    for num in nsw_sequence():
        if is_prime(num):
            count += 1
            if count == n:
                return num
